insert into especialidades (id, nome, codigo, area, nivel, ano, instituicao, imagem_url, descricao, revisao, fonte_url, clube_id) values ('d55af785-7ae7-52a1-bcfc-52b2a8b58974', 'Alívio da Fome', 'AD-001', 'ADRA', '1', '2005', 'Associação Geral', 'https://mda.wiki.br/site/@imgs_wiki/imagem@ad001.png', null, '2026-10-30 14:45:26', 'https://mda.wiki.br/Especialidade_de_Alívio_da_Fome', null) on conflict (codigo) do update set nome = excluded.nome, area = excluded.area, nivel = excluded.nivel, ano = excluded.ano, instituicao = excluded.instituicao, imagem_url = excluded.imagem_url, descricao = excluded.descricao, revisao = excluded.revisao, fonte_url = excluded.fonte_url;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'dece168c-5c0d-5030-a0ec-47f93e76ba02', id, null, 1, '1', 'Ler ou assistir um documentário ou uma matéria jornalística referente ao tema da fome no mundo e discutir com a sua unidade do Clube de Desbravadores as medidas que estão sendo tomados para reduzi-la e apontar como você, desbravador, pode contribuir para esse feito.', '2026-10-30 14:45:26', null from especialidades where codigo = 'AD-001' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'b55aed71-6cc3-5660-9ac4-7fe8ad25e813', id, null, 2, '2', 'Entrevistar uma pessoa que realiza distribuição de alimentos em sua comunidade. Pode ser o líder da ASA de sua igreja, de outra igreja, ou de um centro / restaurante comunitário. Perguntar sobre que tipo de pessoas são atendidas, o que as levam a necessitarem de alimento e como essas necessidades estão sendo satisfeitas. Fazer anotações durante a entrevista e compartilhar os resultados com seu instrutor.', '2026-10-30 14:45:26', null from especialidades where codigo = 'AD-001' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'c599d8a6-ca5f-54e5-b944-4d90265af5e8', id, null, 3, '3', 'Descrever as causas da fome em seu país. Você poderá fazer isso através de uma redação (com, pelo menos, 500 palavras), uma apresentação audiovisual (de, pelo menos, 10 minutos), uma encenação ou produzindo um vídeo de cerca de 1 minuto.', '2026-10-30 14:45:26', null from especialidades where codigo = 'AD-001' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'b268f688-14c5-5cd7-af66-b2a65db39749', id, null, 4, '4', 'Fazer uma coleta de itens alimentícios para a ASA da sua igreja, de outra igreja, ou centro/restaurante comunitário ou, se isso não for possível, escolher uma família que precisa de assistência e lhe entregar os itens coletados. (Obs.: A sugestão é que sejam arrecadados pelo menos 50 alimentos não perecíveis. Deve-se prestar muita atenção ao prazo de validade dos produtos coletados. Produtos com prazo de validade expirado ou com indício de deterioração, como lata estufada, caruncho nas farinhas e feijões, mofo no arroz, etc., não devem ser coletados. Também devem ser levados em consideração os costumes de cada país ou região. Produtos desconhecidos ou que não fazem parte da alimentação do dia a dia tendem a ser mal utilizados ou não utilizados.)', '2026-10-30 14:45:26', null from especialidades where codigo = 'AD-001' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '6f9aae86-b851-5a08-83b8-eed43a1594d6', id, null, 5, '5', 'Visitar um banco de alimentos, um centro de distribuição de alimentos ou um restaurante ou cozinha comunitária e dispor-se como voluntário para ajudar o pessoal que trabalha no estabelecimento. Conversar com eles para saber como os alimentos são obtidos e quais são alguns dos desafios para consegui-los, armazená-los e distribuí-los. Caso não exista nenhum dos estabelecimentos acima descritos em sua região, planejar e auxiliar a ASA na arrecadação de alimentos.', '2026-10-30 14:45:26', null from especialidades where codigo = 'AD-001' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
