insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '05172e3e-2d2b-5ba2-a0f9-801073132699', id, '7f25833c-51a9-54c0-9d38-27616a87e6a7', 10, '2.h', 'Erupções vulcânicas.', '2026-10-30 15:40:47', null from especialidades where codigo = 'AD-005' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'd5cb345d-1e26-5491-a97d-7f1ef8de8a82', id, null, 11, '3', 'As 4 fases na gestão de emergências e desastres são: Prevenção / Mitigação, Preparo, Resposta e Recuperação. Em suas palavras, descrever para o seu instrutor o que cada um desses termos significa e porque são importantes.', '2026-10-30 15:40:47', null from especialidades where codigo = 'AD-005' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '9f2e12ba-5f4b-5b41-aba2-a26d7a293073', id, null, 12, '4', 'O preparo é chave para o sucesso em uma emergência ou desastre. Se você fosse construir um kit para tais circunstâncias, descrever para o seu instrutor quais itens seriam incluídos. Discutir as vantagens de escolher itens movidos à bateria e não à eletricidade, e alimentos não perecíveis em vez de perecíveis.', '2026-10-30 15:40:47', null from especialidades where codigo = 'AD-005' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '6672a51b-c97f-57a0-82e0-918e1ff9becb', id, null, 13, '5', 'Desenhar a planta do local onde você vive. Pensar no que faria em 3 dos desastres relacionadas no requisito 2. Traçar uma rota de fuga de sua casa e discuti-la com seu instrutor e família.', '2026-10-30 15:40:47', null from especialidades where codigo = 'AD-005' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '854ae173-eafe-55bf-8133-a0b9f4fed703', id, null, 14, '6', 'Encontrar 3 histórias na Bíblia que envolveram desastres naturais ou emergências políticas. Colocar-se no lugar das pessoas da história e descrever como esses eventos o afetariam. Discutir como as pessoas nas histórias sobreviveram a essas situações.', '2026-10-30 15:40:47', null from especialidades where codigo = 'AD-005' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '48280259-47cf-5fa5-a394-c11accd81035', id, null, 15, '7', 'Apresentar um breve relatório para o seu Clube de Desbravadores a respeito do que você aprendeu sobre emergências e desastres e de estar preparado para agir nessas circunstâncias. Você pode fazer uma apresentação, encenação, mostrar um breve vídeo ou outro método que melhor transmita o que você aprendeu.', '2026-10-30 15:40:47', null from especialidades where codigo = 'AD-005' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
