insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '397fe881-9b72-58e7-92f6-089e7f037528', id, null, 1, '1', 'Descrever algumas causas gerais porque as pessoas se deslocam para outros países como refugiados. Definir também os termos refugiado, deslocado interno e imigrante.', '2026-10-30 11:52:32', null from especialidades where codigo = 'AD-008' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'c5e0c7d3-cb63-5359-936e-72566cc1e6c6', id, null, 2, '2', 'Listar as necessidades imediatas que um refugiado pode ter quando chega a um novo país. Descrever como você se sentiria se, subitamente, tivesse que enfrentar uma nova língua, cultura e ambiente.', '2026-10-30 11:52:32', null from especialidades where codigo = 'AD-008' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '95de09f2-0daf-56fd-bc31-8bcde9e79cb0', id, null, 3, '3', 'Descobrir que organizações em sua comunidade, país ou no mundo ajudam os refugiados e deslocados internos. Pesquisar sobre o trabalho que eles realizam.', '2026-10-30 11:52:32', null from especialidades where codigo = 'AD-008' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '992362f1-c96c-552e-a5bf-211e696c04a7', id, null, 4, '4', 'Descrever em poucas palavras como você poderia ajudar um refugiado ou um deslocado interno em sua comunidade.', '2026-10-30 11:52:32', null from especialidades where codigo = 'AD-008' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '3b9b562c-1cb4-53b0-bf21-518ff92cd51d', id, null, 5, '5', 'Perguntar a uma pessoa de outro país, que vive em sua comunidade, como ela se ajustou ao novo ambiente. Pedir para que descreva os desafios e contrastes que experimentou durante o processo de adaptação à comunidade.', '2026-10-30 11:52:32', null from especialidades where codigo = 'AD-008' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '9cbbe9a8-160d-5a38-8c9f-e511086f01a0', id, null, 6, '6', 'Fazer um breve relatório para o seu Clube de Desbravadores, igreja, escola sobre o que você aprendeu sobre refugiados e deslocados internos e que desafios eles enfrentam. Você pode levar a efeito este requisito através de uma apresentação audiovisual, encenação, vídeo ou qualquer outra forma que melhor transmita suas descobertas. Discutir porque é importante estar atento à situação dos refugiados e tentar encontrar soluções para esse problema.', '2026-10-30 11:52:32', null from especialidades where codigo = 'AD-008' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '3afe6084-783a-55a9-8f4d-fc26708e9405', id, null, 7, '7', 'Encontrar um refugiado e/ou deslocado interno e auxiliá-lo em parceria com a ASA local. Coloque foto e a descrição do auxílio prestado.', '2026-10-30 11:52:32', null from especialidades where codigo = 'AD-008' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
