insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '8ed99c57-67c6-5bba-9aa0-ab2d86d3189b', id, null, 2, '2', 'Explicar ao seu instrutor porque alguns países são considerados desenvolvidos enquanto outros são chamados de países em desenvolvimento.', '2026-10-30 15:50:23', null from especialidades where codigo = 'AD-009' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '4c3338ba-b4a2-5d31-82ef-70b506db67e8', id, null, 3, '3', 'Mencionar 5 países em desenvolvimento e listar 3 ações que a ADRA realiza neles e que poderiam ser consideradas ações de desenvolvimento e 2 que se caracterizam como ações assistenciais.', '2026-10-30 15:50:23', null from especialidades where codigo = 'AD-009' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '9b3eb45e-f12e-5884-b52c-71acc691c034', id, null, 4, '4', 'Ler a respeito de porque existem pobres entre nós no livro O Libertador ou Deseja de Todas as Nações, de Ellen G. White, capítulo 70 - "Cristo se identifica com os pobres e sofredores". Descrever ao seu instrutor o que você aprendeu.', '2026-10-30 15:50:23', null from especialidades where codigo = 'AD-009' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '67c498b6-7a23-5fa3-ae91-da3a29604d17', id, null, 5, '5', 'Descrever, pelo menos, uma necessidade em seu bairro ou município que requeira atenção.', '2026-10-30 15:50:23', null from especialidades where codigo = 'AD-009' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'ae6a2329-a79c-5706-84ae-649ad48e1a19', id, null, 6, '6', 'Escrever um breve plano de desenvolvimento comunitário que pode ser implementado por seu Clube de Desbravadores (plantio de árvores, limpeza de parques e ruas, pintura de muros, etc.). O plano deve descrever a atividade, o tamanho do grupo, a logística de transporte e materiais e o tempo para completar tal atividade.', '2026-10-30 15:50:23', null from especialidades where codigo = 'AD-009' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '37704484-9053-52eb-b692-9cee6a5eedab', id, null, 7, '7', 'Participar por, pelo menos, 4 horas em uma das seguintes atividades:', '2026-10-30 15:50:23', null from especialidades where codigo = 'AD-009' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'e387ae59-f307-548d-918d-ada9d84faee7', id, '37704484-9053-52eb-b692-9cee6a5eedab', 8, '7.a', 'O desbravador deverá contatar a Ação Solidária Adventista (ASA) de sua igreja e ver em que poderá ajudar. Talvez seja organizando itens doados ou participando de algum projeto por ela já estabelecido. Poderá envolver-se com a coleta e distribuição de alimentos, cobertores, agasalhos, sapatos e outros bens para moradores de rua ou para famílias cadastradas pela ASA. Ainda, poderá apoiar na reparação ou construção de casas para pessoas carentes.', '2026-10-30 15:50:23', null from especialidades where codigo = 'AD-009' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '3e6fc0b1-1caf-521f-a1a4-277993043c72', id, '37704484-9053-52eb-b692-9cee6a5eedab', 9, '7.b', 'O desbravador deverá contatar a ADRA para ver a possibilidade de envolver-se como voluntário em algum projeto que esteja sendo implementado no seu bairro ou município.', '2026-10-30 15:50:23', null from especialidades where codigo = 'AD-009' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'fb61535f-e595-50e3-991c-f625eeecee85', id, '37704484-9053-52eb-b692-9cee6a5eedab', 10, '7.c', 'O desbravador deverá envolver-se com um "Mutirão Social". O alvo deste tipo de mutirão é proporcionar à população menos favorecida acesso a certos serviços de forma gratuita. Alguns destes serviços são: corte de cabelo, testes rápidos para identificar doenças como sífilis, hepatite e AIDS, aferição de pressão arterial, orientações de saúde e nutrição, palestras educativas sobre como economizar energia e gás, recreação infantil, emissão de documento como carteira de trabalho, encaminhamento para vagas de empregos, entre outros. O mutirão pode ser feito no pátio da igreja, num centro comunitário, num ginásio de esportes ou outro local sugerido e autorizado pelas autoridades locais.', '2026-10-30 15:50:23', null from especialidades where codigo = 'AD-009' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '6c8112f7-2eee-5a18-be6a-ebda6629c57e', id, '37704484-9053-52eb-b692-9cee6a5eedab', 11, '7.d', 'O desbravador deverá procurar saber o que sua igreja, outras igrejas, o governo ou organizações comunitárias estão fazendo pelos moradores de rua. Caso a comunidade já tenha esse programa, você poderá unir-se a ele.', '2026-10-30 15:50:23', null from especialidades where codigo = 'AD-009' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
