insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '0ca28852-bc51-598a-a7e3-a5d0440a55e0', id, null, 7, '5', 'Projetar um sistema de lançamento elétrico. Quando tiver sido aprovado pelo seu instrutor, construir este sistema e usá-lo para o lançamento de foguetes, pelo menos, 5 vezes.', '2026-09-09 18:56:19', null from especialidades where codigo = 'HM-036' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'ab1c8a77-6868-52f0-b64a-bb498f5165f8', id, null, 8, '6', 'Descrever e demonstrar controle de altitude de estação única. Com o auxílio de um instrutor, rastrear o mesmo foguete 3 vezes usando 3 diferentes tamanhos de motores e comparar altitudes com um localizador de altitude.', '2026-09-09 18:56:19', null from especialidades where codigo = 'HM-036' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '0229c70f-1e5b-57b7-b60c-be8e135b82cc', id, null, 9, '7', 'Comparar a velocidade e altitude de 2 pesos diferentes de foguetes usando o mesmo tamanho do motor.', '2026-09-09 18:56:19', null from especialidades where codigo = 'HM-036' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '86f275b4-9007-56b6-bed5-a3d106e8892c', id, null, 10, '8', 'Materiais: As miniaturas de foguetes deverão ser produzidas apenas através de materiais leves como papel, madeira, plástico e folhas de papel alumínio, com a exceção dos suportes de cargas e do mecanismo, feitos de arame ou semelhantes.', '2026-09-09 18:56:19', null from especialidades where codigo = 'HM-036' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'f7e6543d-cd65-5ee6-8957-2c3d2cd9a878', id, null, 11, '9', 'Mecanismos: Utilizar apenas mecanismos de miniaturas comprados prontos, e de acordo com as instruções do fabricante. Não mexer com estes motores e utilizá-los somente para fins recomendados pelo fabricante.', '2026-09-09 18:56:19', null from especialidades where codigo = 'HM-036' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '68266e00-ca69-5a02-86e1-23deb4e611ea', id, null, 12, '10', 'Sistema de ignição: Lançar os foguetes com um sistema de lançamento elétrico e ignitores de motores elétricos. O sistema de lançamento deverá possuir uma segurança de encravamento em série com o interruptor de lançamento que usa um interruptor de lançamento que retorne para a posição “OFF” quando lançado.', '2026-09-09 18:56:19', null from especialidades where codigo = 'HM-036' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'b1563379-cd0e-54f5-b4b8-4bd1b70b1f3a', id, null, 13, '11', 'Falhas de ignição: Se o foguete não lançar quando for acionado o botão do sistema de lançamento elétrico, deve-se retirá-lo do lançador de bloqueio de segurança ou desconectar a bateria, e esperar 60 segundos após o último lançamento, antes de permitir que alguém se aproxime do foguete.', '2026-09-09 18:56:19', null from especialidades where codigo = 'HM-036' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'bca88a39-2926-536b-ad38-e6f90b0369ed', id, null, 14, '12', 'Lançamento de segurança: Iniciar uma contagem regressiva antes do lançamento para garantir que todos prestem atenção e mantenham uma distância segura de pelo menos 4,5 metros de distância para lançamentos de foguetes com motores D ou menor, e 9,5 metros para lançamentos de foguetes maiores. Caso o foguete não tenha sido testado e haja incerteza sobre sua segurança ou estabilidade, verificar a estabilidade de voo antes de permitir que espectadores acompanhem o lançamento.', '2026-09-09 18:56:19', null from especialidades where codigo = 'HM-036' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '9dea2837-7a8a-527f-8eb1-2a4469b38818', id, null, 15, '13', 'Lançador: Lançar o foguete a partir de uma haste de lançamento, torre ou ferroviário, apontada a partir de 30 graus da vertical para assegurar que o foguete voe quase em linha reta, usando um defletor para impedir que a explosão escape do motor de bater no chão. Para evitar lesão acidental com os olhos, colocar os lançadores de modo que a extremidade da haste de lançamento esteja acima do nível do olho ou tapar a extremidade da haste, quando não estiver em uso.', '2026-09-09 18:56:19', null from especialidades where codigo = 'HM-036' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select 'bdcf84ad-a4e4-510f-a76b-17e00891db38', id, null, 16, '14', 'Tamanho: O modelo de foguete não pesará mais de 1.500 gramas com o lançamento e não conterá mais de 125 gramas de propelente ou 71,9 segundos de impulso total. Se o modelo de foguete pesa mais de 453 gramas na decolagem ou tem mais de 113 gramas de propelente, verificar e cumprir com os regulamentos da Administração de Avaliação Federal antes de voar.', '2026-09-09 18:56:19', null from especialidades where codigo = 'HM-036' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '227635af-c921-5ff1-9949-a273522a7222', id, null, 17, '15', 'Segurança de voo: Não lançar o foguete contra ventos fortes, perto de prédios, fios de eletricidade, árvores altas, perto de aeroportos ou heliportos (onde passem aeronaves em voo baixo), ou em quaisquer condições que possam ser perigosas às pessoas ou propriedades, e não colocar qualquer carga inflamável ou explosiva no foguete.', '2026-09-09 18:56:19', null from especialidades where codigo = 'HM-036' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '6d060846-33d2-508a-9029-59d53a9c6854', id, null, 18, '16', 'Área de lançamento: Só lançar o foguete numa área aberta, pelo menos, tão grande como mostrado na tabela ( http://nar.org/NARmrsc.html), e em condições de tempo seguros, com velocidades de vento não superior a 32km/h . Assegurar-se de que não há capim seco próximo à plataforma de lançamento, e que o local de lançamento não apresenta risco de incêndios na grama.', '2026-09-09 18:56:19', null from especialidades where codigo = 'HM-036' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '996bb588-01a0-5f68-ac30-cf075444ff39', id, null, 19, '17', 'Sistema de recuperação: Deve-se usar um sistema de recuperação como uma serpentina ou pára-quedas no foguete para que ele retorne com segurança e sem danos, e então possa ser usado novamente. Usar apenas enchimento resistente a chamas ou recuperação à prova de fogo no foguete.', '2026-09-09 18:56:19', null from especialidades where codigo = 'HM-036' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
insert into requisito_especialidade (id, especialidade_id, parent_id, numero, rotulo, texto, revisao, clube_id) select '8e2a741a-05af-585b-b904-fa810de51ed4', id, null, 20, '18', 'Recuperação de forma segura: Não tentar recuperar o foguete caso ele caia em rede elétrica, árvores altas, ou outros lugares perigosos.', '2026-09-09 18:56:19', null from especialidades where codigo = 'HM-036' on conflict (id) do update set texto = excluded.texto, numero = excluded.numero, revisao = excluded.revisao;
